using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Newtonsoft.Json.Linq;
using UnityEngine;

namespace DungeonContract.Editor
{
    public static class DcP2MultiplayerChecks
    {
        private static JObject parameters;
        private static JObject geometry;
        private static readonly List<string> passed=new List<string>();
        private static DcP1World World(int count=2)=>new DcP1World(new JObject{["parameters"]=parameters,["p1_world"]=geometry,["practice"]=false,["weapon_stage"]=true,["p2_stage"]=true,["seed"]=20261012,["run_id"]="p2_mp_model",["members"]=new JArray(Enumerable.Range(0,count).Select(index=>new JObject{["player_id"]=(index+1).ToString(),["slot"]=index,["loadout_id"]=index%2==0?"ranger":"runesmith"}))});
        private static void Require(bool value,string name){if(!value)throw new InvalidOperationException("P2 multiplayer "+name);}
        private static void Case(string name,Action check){check();passed.Add(name);}
        private static DcP1Input Intent(DcP1World world,string id,Vector2 move=default)=>new DcP1Input{Sequence=1,WeaponID=world.ActiveWeapon(id),WeaponRevision=world.WeaponRevision(id),Move=move};
        private static JObject Point(float x,float y)=>new JObject{["x"]=x,["y"]=y};
        public static void Run()
        {
            parameters=JObject.Parse(File.ReadAllText(Path.GetFullPath("../../docs/game-demo/config/parameters-v4-p2-1.json")));geometry=JObject.Parse(File.ReadAllText(Path.GetFullPath("../../docs/game-demo/config/world-v4-p2-1.json")));passed.Clear();
            Case("two and four frozen roster slots",()=>{foreach(var count in new[]{2,4}){var world=World(count);Require(((JArray)world.Snapshot()["players"]).Count==count,"roster");Require(((JArray)world.Snapshot()["players"]).Select(item=>(int)item["slot"]).Distinct().Count()==count,"duplicate slots");}});
            Case("late teammate enters active room after two second warning",()=>{var world=World();var state=world.Capture();state["rooms"][1]["Status"]="active";state["rooms"][1]["Wave"]=3;state["rooms"][1]["Pending"]=new JArray("guard");state["players"][0]["Room"]=1;state["players"][1]["Room"]=8;state["players"][1]["Position"]=Point(5.6f,2.5f);world.Restore(state);world.AdvanceTime(3000);world.Input("2",Intent(world,"2",Vector2.right));world.Tick(3000);Require((int)world.Snapshot()["players"][1]["room_id"]==1,"late door locked");});
            Case("one teammate exit does not end remaining world",()=>{var world=World();world.Leave("1");world.Tick(33);Require(!world.Terminal&&(bool)world.Snapshot()["players"][0]["left"],"host privilege");});
            Case("short disconnect stops input and preserves weapon resources",()=>{var world=World();world.Tick(0);world.Action("1","attack_press",Intent(world,"1"));var magazine=(int)world.Snapshot()["players"][0]["magazine"];world.Presence("1",false);world.Input("1",Intent(world,"1",Vector2.right));world.Tick(33);Require(!(bool)world.Snapshot()["players"][0]["connected"]&&(int)world.Snapshot()["players"][0]["magazine"]==magazine,"disconnect resources");});
            Case("new connection resets ordering only without healing",()=>{var world=World();var state=world.Capture();state["players"][0]["Health"]=31;state["players"][0]["Magazine"]=3;state["players"][0]["Ack"]=100;state["players"][0]["LastActionSequence"]=20;state["players"][0]["AbilityAt"]=12000;world.Restore(state);world.Reconnect("1");Require((int)world.Snapshot()["players"][0]["health"]==31&&(int)world.Snapshot()["players"][0]["magazine"]==3&&(uint)world.Snapshot()["players"][0]["last_action_sequence"]==0&&(uint)world.Snapshot()["players"][0]["last_input_sequence"]==0&&(long)world.Snapshot()["players"][0]["ability_remaining_ms"]==12000,"reconnect reset gameplay");});
            Case("reconnect discards previously authorized old connection actions",()=>{var world=World();var input=Intent(world,"1");input.ActionSequence=1;world.QueueAction("1","attack_press",input,"old_connection_attack");world.Reconnect("1");world.Tick(33);Require(world.Receipt("old_connection_attack")=="stale_connection"&&(int)world.Snapshot()["players"][0]["magazine"]==8&&(uint)world.Snapshot()["players"][0]["last_action_sequence"]==0,"old queued action crossed connection");});
            Case("room interest crops other players exact state",()=>{var world=World();var state=world.Capture();state["players"][1]["Room"]=2;state["players"][1]["Position"]=Point(20,10);world.Restore(state);var snapshot=world.Snapshot();var value=DcP21Interest.ForPlayer(snapshot,"1");Require(((JArray)value["players"]).Count==1&&value["team_rooms"][0]["x"]==null&&(int)value["team_rooms"][0]["room_id"]==2,"room privacy");Require(((JArray)snapshot["players"]).Count==2,"source mutated");});
            Case("per-player camera state follows different rooms",()=>{var world=World();var state=world.Capture();state["players"][1]["Room"]=2;world.Restore(state);var snapshot=world.Snapshot();var first=DcP21Interest.ForPlayer(snapshot,"1");var second=DcP21Interest.ForPlayer(snapshot,"2");Require((int)first["players"][0]["room_id"]==0&&(int)second["players"][0]["room_id"]==2,"shared camera owner");});
Case("binary baseline chunks under 900 and reverse reassembly",()=>{var world=World(4);var value=world.Snapshot();value["state_revision"]=1;var packets=DcP2Baseline.Encode(value,1,2,3);Require(packets.Length>1&&packets.All(item=>item.Length<=900),"chunk budget");var receiver=new DcP2Baseline();JObject result=null;foreach(var packet in packets.Reverse())result=receiver.Receive(packet,2,3,0,0)??result;Require(result!=null&&value.ToString(Newtonsoft.Json.Formatting.None)==result.ToString(Newtonsoft.Json.Formatting.None),"roundtrip");});
            Case("baseline duplicate is idempotent",()=>{var value=World().Snapshot();value["state_revision"]=1;var packets=DcP2Baseline.Encode(value,1,2,3);var receiver=new DcP2Baseline();receiver.Receive(packets[0],2,3,0,0);Require(receiver.Receive(packets[0],2,3,0,0)==null,"duplicate applied");});
            Case("baseline rejects changed duplicate chunk",()=>{var value=World().Snapshot();value["state_revision"]=1;var packet=DcP2Baseline.Encode(value,1,2,3)[0];var receiver=new DcP2Baseline();receiver.Receive(packet,2,3,0,0);packet[packet.Length-1]^=1;var rejected=false;try{receiver.Receive(packet,2,3,0,0);}catch(InvalidDataException){rejected=true;}Require(rejected,"chunk conflict");});
            Case("baseline old source and connection reject",()=>{var value=World().Snapshot();value["state_revision"]=1;var packet=DcP2Baseline.Encode(value,1,2,3)[0];foreach(var binding in new[]{new[]{1L,3L},new[]{2L,4L}}){var rejected=false;try{new DcP2Baseline().Receive(packet,binding[0],binding[1],0,0);}catch(InvalidDataException){rejected=true;}Require(rejected,"old identity");}});
            Case("baseline stale applied revision cannot resurrect entities",()=>{var value=World().Snapshot();value["state_revision"]=1;var packets=DcP2Baseline.Encode(value,1,2,3);var receiver=new DcP2Baseline();Require(packets.All(packet=>receiver.Receive(packet,2,3,0,1)==null),"stale revision");});
            Case("baseline malformed sizes reject before allocation",()=>{var value=World().Snapshot();value["state_revision"]=1;var packet=DcP2Baseline.Encode(value,1,2,3)[0];var invalid=(byte[])packet.Clone();Buffer.BlockCopy(BitConverter.GetBytes(int.MaxValue),0,invalid,25,4);var rejected=false;try{new DcP2Baseline().Receive(invalid,2,3,0,0);}catch(InvalidDataException){rejected=true;}Require(rejected,"total allocation bound");});
            Case("dynamic groups remain separate after room crop",()=>{var world=World(4);var value=DcP21Interest.ForPlayer(world.Snapshot(),"1");var replica=new DcS1Replica();replica.Baseline(value,"1",1);var next=(JObject)value.DeepClone();next["world_frame_id"]=(long)value["world_frame_id"]+1;var packets=DcS1Replica.Encode(next,1,2,3);Require(packets.All(item=>item.Length<=900),"dynamic budget");foreach(var packet in packets.Reverse())Require(replica.Dynamic(packet,2,3),"dynamic reverse");});
            Case("all four permanently leave closes world without waiting",()=>{var world=World(4);foreach(var id in new[]{"1","2","3","4"})world.Leave(id);world.Tick(33);Require(world.Terminal&&world.Outcome=="failed","all leave");});
            Case("baseline send pump bounds frame and replaces superseded pending",()=>{var pump=new DcP2BaselinePump();pump.Enqueue(1,Enumerable.Range(0,20).Select(index=>new[]{(byte)index}).ToArray());pump.Enqueue(1,new[]{new byte[]{100}});pump.Enqueue(1,new[]{new byte[]{200}});var sent=new List<byte>();Require(pump.Drain(1,8,packet=>sent.Add(packet[0]))==8&&sent.Count==8,"unbounded burst");while(pump.Drain(1,8,packet=>sent.Add(packet[0]))>0){}Require(sent.Count==21&&sent.Last()==200&&!sent.Contains(100),"stale pending queue");});
            Case("known downed player cannot continue local movement prediction",()=>{var world=World();var snapshot=world.Snapshot();snapshot["players"][0]["health"]=0;var replica=new DcS1Replica();replica.Baseline(snapshot,"1",1);var prediction=new DcS1Prediction(geometry);prediction.Correct(replica,"1");var start=prediction.Position;prediction.Move(Intent(world,"1",Vector2.right),1f/60,true);Require(prediction.Position==start&&prediction.HistoryCount==0,"downed ghost movement");});
Case("runtime cached snapshot matches immutable snapshot",()=>{var world=World(4);for(var frame=0;frame<80;frame++){world.Input("1",Intent(world,"1",Vector2.right));world.Tick(frame*33);var expected=JObject.Parse(world.Snapshot().ToString());var actual=JObject.Parse(world.RuntimeSnapshot().ToString());Require(JToken.DeepEquals(expected,actual),"snapshot parity");}var cached=world.RuntimeSnapshot();Require(object.ReferenceEquals(cached,world.RuntimeSnapshot()),"cache not reused");});
            File.WriteAllText((DcBootstrap.DemoEvidenceRoot+"/")+(DcV6Profile.Active?"v6-regression-":"")+"p2-multiplayer-model.json",new JObject{["scope"]="two_four_player_world_and_codec_model",["passed"]=passed.Count,["cases"]=new JArray(passed),["real_udp"]=false,["real_storage"]=false,["human"]=false}.ToString());Debug.Log("DC P2 multiplayer model passed "+passed.Count);
        }
    }
}
